import java.io.File;
try {
  containsExt(File dir, String ext) {
    if (!dir.isDirectory()) return false;
    File[] kids = dir.listFiles();
    if (kids == null) return false;
    for (File f : kids) {
      if (f.isDirectory()) { if (containsExt(f, ext)) return true; }
      else if (f.getName().endsWith(ext)) return true;
    }
    return false;
  }
  if (Boolean.parseBoolean("${mixed.language.allowed}")) { return true; }
  File base = new File("${project_basedir_sanitized}");
  boolean mainMixed = containsExt(new File(base,"src/main/java"),".java")
            && containsExt(new File(base,"src/main/scala"),".scala");
  boolean testMixed = containsExt(new File(base,"src/test/java"),".java")
            && containsExt(new File(base,"src/test/scala"),".scala");
  return !(mainMixed || testMixed);
} catch(Exception ex) {
  ex.printStackTrace();
  return false;
}
